    var cb = document.getElementById('cartbtn');
    cb.style.display = count ? 'block' : 'none';
    cb.textContent = '🛒 ' + T('السلة|Cart') + ' (' + count + ') - ' + (total - disc) + ' ' + T('ج.م|EGP');
